CREATE TABLE orders ("order_id" TEXT NOT NULL, "customer_id" TEXT NOT NULL REFERENCES customers(customer_id), "order_status" TEXT, "order_purchase_timestamp" TEXT, "order_approved_at" TEXT, "order_delivered_carrier_date" TEXT, "order_delivered_customer_date" TEXT, "order_estimated_delivery_date" TEXT, PRIMARY KEY (order_id));
CREATE TABLE products ("product_id" TEXT NOT NULL, "product_category_name" TEXT, "product_name_lenght" INTEGER, "product_description_lenght" INTEGER, "product_photos_qty" INTEGER, "product_weight_g" REAL, "product_length_cm" REAL, "product_height_cm" REAL, "product_width_cm" REAL, PRIMARY KEY (product_id));
CREATE TABLE sellers ("seller_id" TEXT NOT NULL, "seller_zip_code_prefix" TEXT, "seller_city" TEXT, "seller_state" TEXT, PRIMARY KEY (seller_id));
CREATE INDEX orders_customer_id ON orders(customer_id);
CREATE INDEX customers_customer_unique_id ON customers(customer_unique_id);
CREATE INDEX order_items_product_id ON order_items(product_id);
CREATE INDEX order_items_seller_id ON order_items(seller_id);
CREATE INDEX order_reviews_order_id ON order_reviews(order_id);
COMMIT;
PRAGMA foreign_keys=ON;
